using System;using System.Linq;using System.Reflection;using System.Windows.Forms;
class SettingsNavigationChecks{static BindingFlags F=BindingFlags.Instance|BindingFlags.NonPublic;[STAThread]static void Main(){Application.EnableVisualStyles();using(var g=new Game()){g.Show();var save=new Save();typeof(Game).GetField("save",F).SetValue(g,save);var filter=(IMessageFilter)typeof(Game).GetField("escapeSettingsFilter",F).GetValue(g);var msg=Message.Create(g.Handle,0x100,new IntPtr((int)Keys.Escape),IntPtr.Zero);filter.PreFilterMessage(ref msg);if(Application.OpenForms.OfType<GuildWordDialog>().Any())throw new Exception("Home ESC opens settings");typeof(Game).GetMethod("ShowWaystationWorldMap",F).Invoke(g,null);using(var timer=new Timer{Interval=150}){timer.Tick+=(s,e)=>{var d=Application.OpenForms.OfType<GuildWordDialog>().FirstOrDefault(x=>x.Text=="游戏设置");if(d==null)return;timer.Stop();var row=d.Controls.OfType<FlowLayoutPanel>().Single();var buttons=row.Controls.OfType<Button>().ToArray();if(string.Join(",",buttons.Select(x=>x.Text))!="继续游戏,返回主界面,保存并退出游戏")throw new Exception("Footer order");buttons[1].PerformClick();};timer.Start();typeof(Game).GetMethod("ShowInGameSettings",F).Invoke(g,new object[]{g});}if((string)typeof(Game).GetField("page",F).GetValue(g)!="home")throw new Exception("Return home failed");g.Close();}Console.WriteLine("PASS home ESC disabled, three footer actions ordered, return to home.");}}
